  cohesion: ["Social cohesion is threatened by growing inequality.", "cohesive (adj).", "La cohesión social se ve amenazada por la creciente desigualdad."],
  consensus: ["There is broad consensus that reform is needed.", "reach / build a consensus ON sth.", "Hay un amplio consenso en que se necesita una reforma."],
  corruption: ["Anti-corruption measures are being strengthened.", "corrupt (adj/verb).", "Se están reforzando las medidas anticorrupción."],
  dissent: ["The bill was passed despite significant dissent.", "dissenter (noun), dissenting voice.", "El proyecto de ley fue aprobado a pesar de una disidencia considerable."],
